import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.Ch_0qWu9.js";const u=JSON.parse('{"title":"Contributing to TCSExam","description":"","frontmatter":{"sourcePath":".github/CONTRIBUTING.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/2195a1c2af3b46d864ca365f3ec640ee39fd3da2/.github/CONTRIBUTING.md","alternateUrl":"/TCSExam/docs/zh/contributing/","alternateAnchors":{"contributing-to-tcsexam":"contributing-to-tcsexam","suggest-a-task-or-correction":"suggest-a-task-or-correction","set-up-a-development-checkout":"set-up-a-development-checkout","check-a-change":"check-a-change","write-public-documentation":"write-public-documentation","export-a-source-package":"export-a-source-package","extend-the-backend-or-task-resources":"extend-the-backend-or-task-resources"}},"headers":[],"relativePath":"contributing/index.md","filePath":"contributing/index.md"}'),n={name:"contributing/index.md"};function r(o,e,c,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="contributing-to-tcsexam" tabindex="-1">Contributing to TCSExam <a class="header-anchor" href="#contributing-to-tcsexam" aria-label="Permalink to &quot;Contributing to TCSExam&quot;">​</a></h1><p>Contribute research tasks, report corrections, or improve code and documentation. This guide is for researchers and developers helping improve TCSExam.</p><h2 id="suggest-a-task-or-correction" tabindex="-1">Suggest a task or correction <a class="header-anchor" href="#suggest-a-task-or-correction" aria-label="Permalink to &quot;Suggest a task or correction&quot;">​</a></h2><p><a href="https://github.com/MoonshotAI/TCSExam/issues" target="_blank" rel="noreferrer">Open a GitHub issue</a> to propose a research problem or report a task issue. Include the problem statement, its source, the relevant track, and how a submission could be checked. For a construction task, include the reference bound and its source.</p><p>For a correction, identify the task and show a concrete example of the problem. If you have an implementation, submit a pull request with the task statement, verification code, and scoring rule. The development instructions below describe the checks to run.</p><h2 id="set-up-a-development-checkout" tabindex="-1">Set up a development checkout <a class="header-anchor" href="#set-up-a-development-checkout" aria-label="Permalink to &quot;Set up a development checkout&quot;">​</a></h2><p>Use Python 3.12 or later and install the runtime, backend and test dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[runtime,backend]&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source-inputs</span></span></code></pre></div><p><code>source-inputs</code> prepares the pinned source archives used by the Lean build recipes and material tests. For an unavailable upstream download, use the <a href="/TCSExam/docs/resources/#prepare-fixed-lean-source-archives">verified local import</a>.</p><h2 id="check-a-change" tabindex="-1">Check a change <a class="header-anchor" href="#check-a-change" aria-label="Permalink to &quot;Check a change&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcsexam.recipes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/tcsexam/backend/tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/tcsexam/tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/source-check.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p><code>validate</code> checks task structure, suite membership, executable scripts and source identities. The test suite covers command configuration, data recipes, scoring, backend behavior and documentation links. <code>check-public --phase source</code> checks the files intended for source distribution, including internal references and distribution rules. Resolve reported errors before exporting.</p><p>For runtime changes, also exercise the affected command or judge with representative inputs. Use the <a href="/TCSExam/docs/judge-execution-isolation/">judge image preflight</a> for execution-isolation changes and the <a href="/TCSExam/docs/backend/service/#writing-a-platform-adapter">adapter contract checks</a> for a platform adapter. Preserve task inputs, scoring definitions and declared resource budgets when changing packaging.</p><p>Keep generated images, downloaded datasets and evaluation outputs in the configured cache or output directory. Build recipes belong under <code>assets/</code>; task definitions belong under <code>tasks/</code> and are selected through <code>suites/tasks.json</code>.</p><h2 id="write-public-documentation" tabindex="-1">Write public documentation <a class="header-anchor" href="#write-public-documentation" aria-label="Permalink to &quot;Write public documentation&quot;">​</a></h2><p>Organize guides around a reader&#39;s task: prerequisites, commands, expected outputs and troubleshooting. Define each configuration option, input procedure and score in one reference page, then link to it from other guides. Keep English and Chinese guides consistent in commands, defaults and behavior.</p><p>Markdown files under <code>docs/</code> are the source for both repository reading and the documentation website. When adding or moving a guide, update the <a href="/TCSExam/docs/">documentation home</a> and the corresponding Chinese navigation. Language links should lead to the same content in the other language; keep reading-path links separate.</p><p>Document limitations where they affect an operation, with the required condition and the action the reader should take. Keep delivery reports, internal reviews, development diaries, execution logs and private infrastructure details outside the source repository. Preserve upstream attribution, license texts, source URLs, fixed versions and content hashes.</p><p>Use relative links for pages and files within this repository. The public repository address is maintained in <code>project.urls.Repository</code> in <code>pyproject.toml</code>. To change it and update both getting-started guides, run <code>python -m tcsexam.project_links --repository-url https://github.com/OWNER/REPOSITORY</code>. Run <code>python -m tcsexam.project_links --check</code> to check consistency.</p><p>The default branch contains evaluation code, Markdown guides and <code>paper.pdf</code>. Website source lives in the <a href="https://github.com/MoonshotAI/TCSExam/tree/gh-pages/website" target="_blank" rel="noreferrer">website directory on <code>gh-pages</code></a>. Its documentation renderer reads the Markdown guides from this branch.</p><h2 id="export-a-source-package" tabindex="-1">Export a source package <a class="header-anchor" href="#export-a-source-package" aria-label="Permalink to &quot;Export a source package&quot;">​</a></h2><p>Use a clean checkout of the intended release commit. From the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --normalize-modes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-public</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/tcsexam-source</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --phase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span></span></code></pre></div><p>The destination must be new or empty. A destination inside the checkout must be under <code>build/</code>. The exporter applies the distribution records and omits Git metadata, caches, job outputs, credentials, reference-answer payloads and declared local-only inputs. The exported tree contains the recipes and acquisition instructions needed to prepare its environments. In the exported checkout, run <code>tcsexam source-inputs</code> before Lean builds or material tests.</p><p>Create public repositories and release archives from the exported directory. Keep the source commit, export manifest and check results with the release records so the published files can be traced to their source. The source checkout can contain reference answers and excluded inputs; publish the exported files with a fresh Git history.</p><p><code>--normalize-modes</code> writes regular files as 0644, executable files as 0755 and directories as 0755 while preserving file contents and executable status. Without this option, export preserves source file modes.</p><p>Image distribution has its own <a href="/TCSExam/docs/licenses/distribution/">component requirements</a>. Use <code>tcsexam check-public --phase release</code> when preparing a distribution that includes published images; that check includes image addresses and anonymous pull access.</p><h2 id="extend-the-backend-or-task-resources" tabindex="-1">Extend the backend or task resources <a class="header-anchor" href="#extend-the-backend-or-task-resources" aria-label="Permalink to &quot;Extend the backend or task resources&quot;">​</a></h2><ul><li><a href="/TCSExam/docs/backend/service/#writing-a-platform-adapter">Platform adapter contract</a>: worker creation, file transfer, execution, resource accounting and cleanup.</li><li><a href="/TCSExam/docs/solver-backend/">Backend HTTP protocol</a>: client requests, credentials, session state and submission handling.</li><li><a href="/TCSExam/docs/resources/assets/">Resource inventories</a>: image dependencies, source inputs and distribution records.</li><li><a href="/TCSExam/docs/backend/public-images/">Public self-test images</a>: separate public data from hidden judging data in every image layer.</li><li><a href="/TCSExam/docs/oracle-answers/">Reference-answer archives</a>: package separately supplied answers for operator use.</li></ul>`,29)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
